func TestNewServerHTTPContract(t *testing.T) {
	server := NewServer("127.0.0.1:0", []Account{
		{ID: "b", Name: "Beta", Cents: 200, Active: false},
		{ID: "a", Name: "Alpha", Cents: 100, Active: true},
	})

	tests := []struct {
		name       string
		method     string
		path       string
		wantStatus int
		wantBody   string
		wantAllow  string
	}{
		{
			name:       "health",
			method:     http.MethodGet,
			path:       "/healthz",
			wantStatus: http.StatusOK,
			wantBody:   "ok",
		},
		{
			name:       "all accounts are sorted",
			method:     http.MethodGet,
			path:       "/accounts",
			wantStatus: http.StatusOK,
			wantBody:   "[{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true},{\"id\":\"b\",\"name\":\"Beta\",\"cents\":200,\"active\":false}]\n",
		},
		{
			name:       "active accounts",
			method:     http.MethodGet,
			path:       "/accounts?active=true",
			wantStatus: http.StatusOK,
			wantBody:   "[{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true}]\n",
		},
		{
			name:       "invalid active value",
			method:     http.MethodGet,
			path:       "/accounts?active=maybe",
			wantStatus: http.StatusBadRequest,
			wantBody:   "invalid query parameter \"active\"\n",
		},
		{
			name:       "account",
			method:     http.MethodGet,
			path:       "/accounts/a",
			wantStatus: http.StatusOK,
			wantBody:   "{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true}\n",
		},
		{
			name:       "unknown account",
			method:     http.MethodGet,
			path:       "/accounts/missing",
			wantStatus: http.StatusNotFound,
			wantBody:   "404 page not found\n",
		},
		{
			name:       "unknown path",
			method:     http.MethodGet,
			path:       "/other",
			wantStatus: http.StatusNotFound,
			wantBody:   "404 page not found\n",
		},
		{
			name:       "known path with wrong method",
			method:     http.MethodPost,
			path:       "/accounts",
			wantStatus: http.StatusMethodNotAllowed,
			wantBody:   "Method Not Allowed\n",
			wantAllow:  http.MethodGet,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			request := httptest.NewRequest(test.method, test.path, nil)
			response := httptest.NewRecorder()
			server.Handler.ServeHTTP(response, request)
			result := response.Result()
			body, err := io.ReadAll(result.Body)
			_ = result.Body.Close()
			if err != nil {
				t.Fatalf("io.ReadAll(%s %s) error = %v", test.method, test.path, err)
			}

			if result.StatusCode != test.wantStatus {
				t.Errorf("HTTP request %s %s status = %d, want %d", test.method, test.path, result.StatusCode, test.wantStatus)
			}
			if string(body) != test.wantBody {
				t.Errorf("HTTP request %s %s body = %q, want %q", test.method, test.path, body, test.wantBody)
			}
			if result.Header.Get("Allow") != test.wantAllow {
				t.Errorf("HTTP request %s %s Allow = %q, want %q", test.method, test.path, result.Header.Get("Allow"), test.wantAllow)
			}
		})
	}
}

