	query, err := url.ParseQuery(r.URL.RawQuery)
	if err != nil || len(query["active"]) > 1 {
		http.Error(w, `invalid query parameter "active"`, http.StatusBadRequest)
		return
	}

	filtered := make([]Account, 0, len(accounts))
	values, hasFilter := query["active"]
	if !hasFilter {
		filtered = append(filtered, accounts...)
		writeJSON(w, filtered)
		return
	}
	if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
		http.Error(w, `invalid query parameter "active"`, http.StatusBadRequest)
		return
	}
	active := values[0] == "true"
	for _, account := range accounts {
		if account.Active == active {
			filtered = append(filtered, account)
		}
	}
	writeJSON(w, filtered)
}

func serveAccount(w http.ResponseWriter, r *http.Request, accounts []Account, id string) {
	for _, account := range accounts {
		if account.ID == id {
			writeJSON(w, account)
			return
		}
	}
	http.NotFound(w, r)
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(value)
