// Package gateway serves the public read-only accounts API.
package gateway

import (
	"encoding/json"
	"net/http"
	"net/url"
	"slices"
	"sort"
	"strings"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

const (
	healthzPath     = "/healthz"
	accountsPath    = "/accounts"
	accountsPrefix  = "/accounts/"
	activeParamName = "active"
)

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	accounts = slices.Clone(accounts)
	sort.SliceStable(accounts, func(i, j int) bool {
		return accounts[i].ID < accounts[j].ID
	})

	return &http.Server{
		Addr:                addr,
		Handler:             &accountsHandler{accounts: accounts},
		ReadHeaderTimeout:   5 * time.Second,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		IdleTimeout:         60 * time.Second,
		MaxHeaderBytes:      1 << 20,
		MaxHeaderValueCount: 100,
	}
}

// accountsHandler serves the routes documented on NewServer.
type accountsHandler struct {
	accounts []Account
}

func (h *accountsHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	if !isKnownPath(path) {
		http.NotFound(w, r)
		return
	}
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
		return
	}

	switch {
	case path == healthzPath:
		serveHealthz(w)
	case path == accountsPath:
		h.serveList(w, r)
	default:
		h.serveGet(w, r, path[len(accountsPrefix):])
	}
}

func isKnownPath(path string) bool {
	return path == healthzPath || path == accountsPath || isAccountPath(path)
}

func isAccountPath(path string) bool {
	rest, ok := strings.CutPrefix(path, accountsPrefix)
	return ok && rest != "" && !strings.Contains(rest, "/")
}

func serveHealthz(w http.ResponseWriter) {
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

func (h *accountsHandler) serveList(w http.ResponseWriter, r *http.Request) {
	query, err := url.ParseQuery(r.URL.RawQuery)
	if err != nil || len(query[activeParamName]) > 1 {
		writeInvalidActiveParam(w)
		return
	}

	filtered := make([]Account, 0, len(h.accounts))
	values, hasActive := query[activeParamName]
	if !hasActive {
		writeJSON(w, append(filtered, h.accounts...))
		return
	}
	if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
		writeInvalidActiveParam(w)
		return
	}

	active := values[0] == "true"
	for _, account := range h.accounts {
		if account.Active == active {
			filtered = append(filtered, account)
		}
	}
	writeJSON(w, filtered)
}

func writeInvalidActiveParam(w http.ResponseWriter) {
	http.Error(w, `invalid query parameter "active"`, http.StatusBadRequest)
}

func (h *accountsHandler) serveGet(w http.ResponseWriter, r *http.Request, id string) {
	for _, account := range h.accounts {
		if account.ID == id {
			writeJSON(w, account)
			return
		}
	}
	http.NotFound(w, r)
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(value)
}

