package gateway

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func testAccounts() []Account {
	return []Account{
		{ID: "b1", Name: "Bravo", Cents: 200, Active: false},
		{ID: "a1", Name: "Alpha", Cents: 100, Active: true},
		{ID: "c1", Name: "Charlie", Cents: 300, Active: true},
	}
}

func testHandler(t *testing.T) http.Handler {
	t.Helper()
	srv := NewServer(":0", testAccounts())
	return srv.Handler
}

func doRequest(t *testing.T, handler http.Handler, method, target string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, target, nil)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	return rec
}

func TestHealthz(t *testing.T) {
	rec := doRequest(t, testHandler(t), http.MethodGet, "/healthz")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusOK)
	}
	if rec.Body.String() != "ok" {
		t.Fatalf("body = %q, want %q", rec.Body.String(), "ok")
	}
}

func TestHealthzWrongMethod(t *testing.T) {
	rec := doRequest(t, testHandler(t), http.MethodPost, "/healthz")
	if rec.Code != http.StatusMethodNotAllowed {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusMethodNotAllowed)
	}
	if got := rec.Header().Get("Allow"); got != http.MethodGet {
		t.Fatalf("Allow = %q, want %q", got, http.MethodGet)
	}
	want := http.StatusText(http.StatusMethodNotAllowed) + "\n"
	if rec.Body.String() != want {
		t.Fatalf("body = %q, want %q", rec.Body.String(), want)
	}
}

func TestUnknownPath(t *testing.T) {
	rec := doRequest(t, testHandler(t), http.MethodGet, "/nope")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusNotFound)
	}
}

